        "止损与目标": "止损放在信号棒低点、回踩低点或最近结构摆动低点下方；第一目标区参考前高、突破测量位或通道上沿。",
        "放弃条件 / 常见错误": "放弃条件：信号棒太弱、触发后无跟随、进入交易区间中部、目标空间小于结构风险，或市场周期已经从趋势转为震荡。常见误判：只看名称，不看背景与触发。",
        "实盘提醒": "实盘提醒：条件胜率不是固定胜率；市场周期、趋势强度、K线背景、成交触发、止损距离、目标位置和风险收益比必须一起评估。"
