      "course": "opening",
      "courseLabel": "开盘专题",
      "kind": "pattern",
      "page": 7,
      "patternNo": 1,
      "title": "001 Trend From The Open Bull：多头趋势从开盘",
      "grade": "A+",
      "cycle": "开盘前60-90分钟 / 强趋势优先",
      "summary": "开盘背景：平开或轻微缺口后的开盘前60-90分钟，先判断趋势从开盘还是进入区间。 识别条件：前几根K线是否连续收在高位/低位、影线是否反复、回踩是否浅、突破后是否有跟随。",
      "details": {
        "开盘背景 / 识别条件": "开盘背景：平开或轻微缺口后的开盘前60-90分钟，先判断趋势从开盘还是进入区间。 识别条件：前几根K线是否连续收在高位/低位、影线是否反复、回踩是否浅、突破后是否有跟随。",
        "入场触发": "入场触发：等待信号棒完成；只有后续K线突破信号棒高点上方虚线才算多头触发。开盘突破类还要有强收盘和跟随K线。",
        "止损与第一目标区": "止损：放在开盘回踩低点、信号棒低点、开盘区间另一侧或突破失败点下方；第一目标区参考开盘测量目标、前日高点、缺口填补区或当日新高。",
        "放弃条件 / 常见误判": "放弃条件：K线重叠太多、突破无跟随、快速回到区间、进入区间中轴、止损过大、目标空间不足或前5分钟波动过度混乱。常见误判：把第一根大K线当成必然趋势。",
        "实盘提醒": "实盘提醒：开盘条件胜率不是固定胜率；缺口、开盘价、开盘区间、跟随K线、止损距离与目标空间必须一起评估。"
      },
